-- =============================================================================
-- TIMESTAMP TRIGGER FUNCTION
-- =============================================================================
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ language 'plpgsql';

-- =============================================================================
-- TIMESTAMP TRIGGERS
-- =============================================================================
DROP TRIGGER IF EXISTS trg_netsuite_accounts_updated_at ON netsuite_accounts;
CREATE TRIGGER trg_netsuite_accounts_updated_at BEFORE UPDATE ON netsuite_accounts FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
DROP TRIGGER IF EXISTS trg_netsuite_accountingperiods_updated_at ON netsuite_accountingperiods;
